import org.openpatch.scratch.*;

/// Deine Spielwelt. Hier stellst du alles auf, was im Spiel vorkommt.
public class Welt extends Spielwelt {

   /// So viele Münzen hat der Spieler schon eingesammelt.
   private int punkte = 0;
   /// So viele Münzen liegen insgesamt in der Welt.
   private int anzahlMuenzen = 0;
   /// So oft darf ein Gegner den Spieler noch erwischen.
   private int leben = 3;
   /// Hier steht der Spieler am Anfang und nach jedem Treffer.
   private double startX;
   private double startY;
   /// So viele Sekunden bleiben noch.
   private double zeit = 30;
   /// Solange das true ist, läuft das Spiel noch.
   private boolean laeuft = true;
   /// Die Anzeige oben links.
   private Text anzeige;
   /// Die besten Zeiten in Sekunden, aufsteigend sortiert. Nur die ersten anzahlBestzeiten Stellen zählen.
   private double[] bestzeiten = new double[5];
   private int anzahlBestzeiten = 0;
   /// Die Anzeige der Bestenliste.
   private Text bestenliste;
   /// Die Spielfigur. Sie ist eine Variable der Welt, damit run() sie anhalten kann.
   private Spieler held;

   /// Der Plan der Welt: jede Zeichenkette eine Zeile, jedes Zeichen ein Feld von 48 × 48 Pixeln.
   /// `#` Stein, `B` Baum, `T` Tanne, `F` Fels, `M` Münze, `H` Herz, `X` Falle,
   /// `G` Schleim, `V` Fledermaus, `S` Start, `.` Wiese
   private String[] plan = {
      "################",
      "#S.....M.......#",
      "#..B.......F...#",
      "#......M.....V.#",
      "#.M.....T....M.#",
      "#..X......G....#",
      "#..M..B....M.H.#",
      "#..G......M....#",
      "################"
   };

   /// Was auf welchem Feld liegt. Ein leeres Feld enthält null.
   /// Das Gitter und die Bühne verweisen auf dieselben Objekte.
   private Gegenstand[][] gegenstaende = new Gegenstand[plan.length][plan[0].length()];

   public Welt() {
      this.addSound("muenze", "assets/audio/sounds/bonus/coin.ogg");
      held = new Spieler("boy");

      for (int z = 0; z < plan.length; z++) {
         for (int s = 0; s < plan[z].length(); s++) {
            char zeichen = plan[z].charAt(s);
            double x = this.zuX(s);
            double y = this.zuY(z);
            if (zeichen == '#') {
               this.setze(new Stein(), x, y);
            } else if (zeichen == 'B') {
               this.setze(new Pflanze(0, 0), x, y);
            } else if (zeichen == 'T') {
               this.setze(new Pflanze(32, 0), x, y);
            } else if (zeichen == 'F') {
               this.setze(new Pflanze(256, 128), x, y);
            } else if (zeichen == 'X') {
               this.setzeGegenstand(new Falle(), z, s);
            } else if (zeichen == 'G') {
               this.setze(new Schleim(), x, y);
            } else if (zeichen == 'V') {
               this.setze(new Fledermaus(), x, y);
            } else if (zeichen == 'S') {
               startX = x;
               startY = y;
               held.setPosition(x, y);
            }
         }
      }

      this.verteileGegenstaende();

      anzeige = new Text("", 0, 200, 700);
      anzeige.setTextSize(20);
      anzeige.setTextColor(255, 255, 255);
      this.add(anzeige);

      bestenliste = new Text("", 290, 140, 160);
      bestenliste.setTextSize(16);
      bestenliste.setTextColor(255, 255, 255);
      this.add(bestenliste);

      this.add(held);
   }

   /// Legt auf jedes M im Plan eine Münze und auf jedes H ein Herz und zählt die Münzen.
   private void verteileGegenstaende() {
      anzahlMuenzen = 0;
      for (int z = 0; z < plan.length; z++) {
         for (int s = 0; s < plan[z].length(); s++) {
            char zeichen = plan[z].charAt(s);
            if (zeichen == 'M') {
               this.setzeGegenstand(new Muenze(), z, s);
               anzahlMuenzen = anzahlMuenzen + 1;
            } else if (zeichen == 'H') {
               this.setzeGegenstand(new Herz(), z, s);
            }
         }
      }
   }

   /// Beginnt eine neue Runde: alle Münzen zurück, Zeit und Leben voll, Spieler an den Start.
   private void neueRunde() {
      this.remove(Muenze.class);
      this.remove(Herz.class);
      this.verteileGegenstaende();
      punkte = 0;
      leben = 3;
      zeit = 30;
      laeuft = true;
      held.setPosition(startX, startY);
      held.setTempo(3);
   }

   /// Sortiert pSekunden in die Bestenliste ein, wie beim Sortieren durch Einfügen:
   /// Alle langsameren Zeiten rücken eine Stelle nach hinten. Ist die Liste voll, fällt die letzte heraus.
   private void trageEin(double pSekunden) {
      int i = anzahlBestzeiten;
      if (i == bestzeiten.length) {
         i = i - 1;
         if (bestzeiten[i] <= pSekunden) {
            return;   // langsamer als alle in der vollen Liste
         }
      } else {
         anzahlBestzeiten = anzahlBestzeiten + 1;
      }
      while (i > 0 && bestzeiten[i - 1] > pSekunden) {
         bestzeiten[i] = bestzeiten[i - 1];
         i = i - 1;
      }
      bestzeiten[i] = pSekunden;
   }

   /// Zeigt die Bestenliste an, eine Zeit je Zeile.
   private void zeigeBestenliste() {
      String text = "Bestzeiten";
      for (int i = 0; i < anzahlBestzeiten; i++) {
         text = text + "\n" + (i + 1) + ". " + (int) bestzeiten[i] + " s";
      }
      bestenliste.showText(text);
   }

   /// Mit der Leertaste beginnt nach dem Ende eine neue Runde.
   public void whenKeyPressed(KeyCode pTaste) {
      if (pTaste == KeyCode.SPACE && !laeuft) {
         this.neueRunde();
      }
   }

   /// Die x-Koordinate der Mitte von Spalte pSpalte. Spalte 0 liegt ganz links.
   private double zuX(int pSpalte) {
      return -360 + pSpalte * 48;
   }

   /// Die y-Koordinate der Mitte von Zeile pZeile. Zeile 0 liegt ganz oben.
   private double zuY(int pZeile) {
      return 192 - pZeile * 48;
   }

   /// Die Spalte, in der die x-Koordinate pX liegt.
   private int zuSpalte(double pX) {
      return (int) Math.round((pX + 360) / 48);
   }

   /// Die Zeile, in der die y-Koordinate pY liegt.
   private int zuZeile(double pY) {
      return (int) Math.round((192 - pY) / 48);
   }

   /// Legt pGegenstand auf das Feld in Zeile pZeile und Spalte pSpalte: auf die Bühne und ins Gitter.
   private void setzeGegenstand(Gegenstand pGegenstand, int pZeile, int pSpalte) {
      pGegenstand.setFeld(pZeile, pSpalte);
      gegenstaende[pZeile][pSpalte] = pGegenstand;
      this.setze(pGegenstand, this.zuX(pSpalte), this.zuY(pZeile));
   }

   /// Nimmt pGegenstand von der Bühne und aus dem Gitter.
   /// Fehlt die zweite Zeile, steht im Gitter weiter ein Verweis auf ein Objekt, das man nicht mehr sieht.
   public void entferne(Gegenstand pGegenstand) {
      pGegenstand.remove();
      gegenstaende[pGegenstand.getZeile()][pGegenstand.getSpalte()] = null;
   }

   /// Sagt allen Gegenständen auf den acht Nachbarfeldern des Spielers Bescheid.
   private void meldeNachbarn() {
      int zeile = this.zuZeile(held.getY());
      int spalte = this.zuSpalte(held.getX());
      for (int z = zeile - 1; z <= zeile + 1; z++) {
         for (int s = spalte - 1; s <= spalte + 1; s++) {
            boolean imGitter = z >= 0 && z < gegenstaende.length && s >= 0 && s < gegenstaende[z].length;
            if (imGitter && gegenstaende[z][s] != null) {
               gegenstaende[z][s].inDerNaehe();
            }
         }
      }
   }

   /// Stellt pFigur an die Stelle (pX, pY) auf die Bühne.
   private void setze(Sprite pFigur, double pX, double pY) {
      pFigur.setPosition(pX, pY);
      this.add(pFigur);
   }

   /// Liefert true, wenn alle Münzen eingesammelt sind.
   private boolean istGewonnen() {
      return punkte == anzahlMuenzen;
   }

   /// Hält das Spiel an und zeigt pMeldung an.
   private void beende(String pMeldung) {
      laeuft = false;
      held.setTempo(0);
      anzeige.showText(pMeldung);
   }

   /// Eine Münze meldet, dass sie eingesammelt wurde.
   public void muenzeEingesammelt() {
      punkte = punkte + 1;
      this.playSound("muenze");
   }

   /// Ein Herz gibt ein Leben zurück, höchstens bis fünf.
   public void heile() {
      if (leben < 5) {
         leben = leben + 1;
      }
   }

   /// Ein Gegner oder eine Falle hat den Spieler erwischt: ein Leben weniger, zurück zum Start.
   public void verletze() {
      if (laeuft) {
         leben = leben - 1;
         held.setPosition(startX, startY);
         if (leben == 0) {
            this.beende("Kein Leben mehr! " + punkte + " von " + anzahlMuenzen + " Münzen. Leertaste: neue Runde");
         }
      }
   }

   /// Wird immer wieder ausgeführt, etwa 60-mal in der Sekunde.
   public void run() {
      if (laeuft) {
         zeit = zeit - 1.0 / 60;
         this.meldeNachbarn();

         if (this.istGewonnen()) {
            this.trageEin(30 - zeit);
            this.zeigeBestenliste();
            this.beende("Gewonnen in " + (int) (30 - zeit) + " Sekunden! Leertaste: neue Runde");
         } else if (zeit <= 0) {
            this.beende("Die Zeit ist um! " + punkte + " von " + anzahlMuenzen + " Münzen. Leertaste: neue Runde");
         } else {
            anzeige.showText("Münzen: " + punkte + " von " + anzahlMuenzen + "   Leben: " + leben + "   Zeit: " + (int) zeit);
         }
      }
   }
}

import org.openpatch.scratch.*;

/// Startet das Spiel.
void main() {
   // Pixelgrafik bleibt beim Vergrößern scharf.
   Window.useTextureSampling(TextureSampling.POINT);
   Window fenster = new Window(768, 432);
   fenster.setStage(new Welt());
}

/// Eine Stachelfalle. Sie ist versteckt, bis der Spieler direkt daneben steht,
/// bleibt dann sichtbar und kostet jedes Mal ein Leben.
public class Falle extends Gegenstand {

   public Falle() {
      this.addCostume("falle", "assets/backgrounds/tilesets/tileset-dungeon.png", 64, 16, 16, 16);
      this.hide();
   }

   public void beruehrtVon(Welt pWelt) {
      pWelt.verletze();
   }

   public void inDerNaehe() {
      this.show();
   }
}

/// Eine Fledermaus fliegt senkrecht auf und ab und kehrt an Hindernissen um.
public class Fledermaus extends Gegner {

   private int tempo = 3;

   public Fledermaus() {
      super("assets/actor/monster/blue-bat/sprite-sheet.png");
   }

   protected void bewege() {
      this.changeY(tempo);
      if (this.getTouchingSprite(Hindernis.class) != null) {
         this.changeY(-tempo);
         tempo = -tempo;
      }
   }
}

import org.openpatch.scratch.*;

/// Etwas, das auf einem Feld des Plans liegt und etwas tut, wenn der Spieler es berührt.
/// Was genau, legt jede Unterklasse selbst fest.
public abstract class Gegenstand extends AnimatedSprite {

   /// Das Feld im Plan, auf dem der Gegenstand liegt.
   private int zeile;
   private int spalte;

   public Gegenstand() {
      this.setSize(300);
   }

   /// Wird aufgerufen, wenn der Spieler diesen Gegenstand berührt.
   public abstract void beruehrtVon(Welt pWelt);

   /// Wird aufgerufen, solange der Spieler auf einem Nachbarfeld steht. Normalerweise passiert nichts.
   public void inDerNaehe() {
   }

   public void setFeld(int pZeile, int pSpalte) {
      zeile = pZeile;
      spalte = pSpalte;
   }

   public int getZeile() {
      return zeile;
   }

   public int getSpalte() {
      return spalte;
   }
}

import org.openpatch.scratch.*;

/// Ein Monster, das sich von selbst bewegt. Wie, legt jede Unterklasse in bewege() fest.
public abstract class Gegner extends AnimatedSprite {

   /// pBild ist ein Bild aus assets/actor/monster/ im Aufbau der Figuren: eine Spalte je Blickrichtung.
   public Gegner(String pBild) {
      this.addAnimation("laufen", pBild, 4, 16, 16, 0, true);
      this.setAnimationInterval(200);
      this.setSize(250);
      // Nur die Füße zählen: So kann die Figur vor einem Baum stehen, ohne an ihm hängen zu bleiben.
      this.setHitbox(4, 10, 12, 10, 12, 16, 4, 16);
   }

   public void run() {
      this.playAnimation("laufen");
      this.bewege();
   }

   /// Bewegt den Gegner um einen Schritt.
   protected abstract void bewege();
}

/// Ein Herz gibt ein Leben zurück und verschwindet.
public class Herz extends Gegenstand {

   public Herz() {
      this.addCostume("herz", "assets/items/potion/heart.png");
   }

   public void beruehrtVon(Welt pWelt) {
      pWelt.entferne(this);
      pWelt.heile();
   }
}

import org.openpatch.scratch.*;

/// Fertig für dich: eine Figur, durch die der Spieler nicht hindurchlaufen kann.
/// Ein Hindernis ist ein Sprite wie jedes andere. Sein Kostüm gibst du ihm selbst.
public class Hindernis extends Sprite {

   public Hindernis() {
      // Die Bilder sind winzig. Dreifach vergrößert passen sie zum Spieler.
      this.setSize(300);
   }

   /// Wie addCostume von Sprite. Zusätzlich hält nur die untere Hälfte des Bildes auf,
   /// also der Stamm eines Baums oder der Fuß eines Felsens. Hinter dem Rest kann man vorbeigehen.
   public void addCostume(String pName, String pBild, int pX, int pY, int pBreite, int pHoehe) {
      super.addCostume(pName, pBild, pX, pY, pBreite, pHoehe);
      this.setHitbox(0, pHoehe / 2.0, pBreite, pHoehe / 2.0, pBreite, pHoehe, 0, pHoehe);
   }
}

/// Eine Münze, die sich dreht, bis der Spieler sie einsammelt.
public class Muenze extends Gegenstand {

   public Muenze() {
      // Vier Bilder zu je 10 × 10 Pixeln nebeneinander.
      this.addAnimation("drehen", "assets/items/treasure/coin2.png", 4, 10, 10);
      this.setAnimationInterval(150);
   }

   public void run() {
      this.playAnimation("drehen");
   }

   public void beruehrtVon(Welt pWelt) {
      pWelt.entferne(this);
      pWelt.muenzeEingesammelt();
   }
}

/// Eine große Pflanze oder ein Felsen, 32 × 32 Pixel aus dem Natur-Kachelbild.
/// pBildX und pBildY geben die linke obere Ecke im Kachelbild an.
public class Pflanze extends Hindernis {

   public Pflanze(int pBildX, int pBildY) {
      this.addCostume("pflanze", "assets/backgrounds/tilesets/tileset-nature.png", pBildX, pBildY, 32, 32);
   }
}

/// Ein Schleim kriecht waagerecht hin und her und kehrt an Hindernissen um.
public class Schleim extends Gegner {

   private int tempo = 2;

   public Schleim() {
      super("assets/actor/monster/slime/slime.png");
   }

   protected void bewege() {
      this.changeX(tempo);
      if (this.getTouchingSprite(Hindernis.class) != null) {
         this.changeX(-tempo);
         tempo = -tempo;
      }
   }
}

import org.openpatch.scratch.*;

/// Die Figur, die du mit den Pfeiltasten steuerst.
/// Sie bleibt an Hindernissen hängen, berührt Gegenstände und meldet der Welt, wenn ein Gegner sie erwischt.
public class Spieler extends AnimatedSprite {

   /// So viele Pixel geht der Spieler in jedem Bild.
   private int tempo = 3;

   /// Erzeugt einen Spieler. pFigur ist ein Ordner in assets/actor/character/, zum Beispiel "boy".
   public Spieler(String pFigur) {
      String bild = "assets/actor/character/" + pFigur + "/sprite-sheet.png";
      // Im Bild steht jede Blickrichtung in einer eigenen Spalte,
      // die vier Schritte untereinander.
      this.addAnimation("unten", bild, 4, 16, 16, 0, true);
      this.addAnimation("oben", bild, 4, 16, 16, 1, true);
      this.addAnimation("links", bild, 4, 16, 16, 2, true);
      this.addAnimation("rechts", bild, 4, 16, 16, 3, true);
      this.setAnimationInterval(150);
      this.setSize(250);
      // Nur die Füße zählen: So kann die Figur vor einem Baum stehen, ohne an ihm hängen zu bleiben.
      this.setHitbox(4, 10, 12, 10, 12, 16, 4, 16);
   }

   public void run() {
      double altX = this.getX();
      double altY = this.getY();

      if (this.isKeyPressed(KeyCode.RIGHT)) {
         this.changeX(tempo);
         this.playAnimation("rechts");
      } else if (this.isKeyPressed(KeyCode.LEFT)) {
         this.changeX(-tempo);
         this.playAnimation("links");
      } else if (this.isKeyPressed(KeyCode.UP)) {
         this.changeY(tempo);
         this.playAnimation("oben");
      } else if (this.isKeyPressed(KeyCode.DOWN)) {
         this.changeY(-tempo);
         this.playAnimation("unten");
      }

      // In ein Hindernis hineingelaufen? Dann zurück auf den alten Platz.
      if (this.getTouchingSprite(Hindernis.class) != null) {
         this.setPosition(altX, altY);
      }

      Welt welt = (Welt) this.getStage();

      // Was der Gegenstand tut, entscheidet der Gegenstand selbst.
      Gegenstand g = this.getTouchingSprite(Gegenstand.class);
      if (g != null) {
         g.beruehrtVon(welt);
      }

      if (this.getTouchingSprite(Gegner.class) != null) {
         welt.verletze();
      }
   }

   /// Legt fest, wie viele Pixel der Spieler in jedem Bild geht. Mit 0 bleibt er stehen.
   public void setTempo(int pTempo) {
      tempo = pTempo;
   }
}

import org.openpatch.scratch.*;

/// Fertig für dich: die Wiese als Hintergrund und die Reihenfolge, in der gezeichnet wird.
public class Spielwelt extends Stage {

   /// So viele Pixel ist eine Kachel auf der Bühne breit und hoch.
   public static final int KACHEL = 48;

   public Spielwelt() {
      // Die Wiese ist ein einziges Bild, so groß wie die Bühne.
      this.addBackdrop("wiese", "assets/backgrounds/wiese.png");

      // Wer weiter unten steht, ist näher am Betrachter: Er wird später gezeichnet
      // und verdeckt, was hinter ihm steht. So läuft man hinter Bäumen vorbei.
      this.getSorting().byY();
   }
}

/// Ein Stein für Mauern, 16 × 16 Pixel aus dem Dungeon-Kachelbild.
public class Stein extends Hindernis {

   public Stein() {
      this.addCostume("stein", "assets/backgrounds/tilesets/tileset-dungeon.png", 128, 48, 16, 16);
   }
}
